package za.ac.richfield.smartpantry;
import android.app.*;import android.os.*;import android.database.*;import android.widget.*;import java.util.*;
public class EditActivity extends Activity {
 Db db;long id;EditText name,qty,unit,expiry;
 @Override public void onCreate(Bundle b){super.onCreate(b);db=new Db(this);id=getIntent().getLongExtra("id",0);LinearLayout l=Ui.page(this,id>0?"Edit ingredient":"Add ingredient");String n="",q="",u="piece",e="";if(id>0)try(Cursor c=db.getReadableDatabase().rawQuery("SELECT name,quantity,unit,expiry FROM pantry WHERE id=?",new String[]{""+id})){if(c.moveToFirst()){n=c.getString(0);q=""+c.getDouble(1);u=c.getString(2);e=c.getString(3);}}name=Ui.input(this,l,"Ingredient name",n);qty=Ui.input(this,l,"Quantity (positive number)",q);qty.setInputType(8194);unit=Ui.input(this,l,"Unit: g, kg, ml, l, piece, slice",u);expiry=Ui.input(this,l,"Expiry YYYY-MM-DD (optional)",e==null?"":e);Ui.button(this,l,"Save ingredient",()->save());if(id>0)Ui.button(this,l,"Delete ingredient",()->new AlertDialog.Builder(this).setMessage("Delete this ingredient?").setPositiveButton("Delete",(d,w)->{db.delete(id);finish();}).setNegativeButton("Cancel",null).show());Ui.button(this,l,"Cancel",()->finish());}
 void save(){String n=name.getText().toString().trim(),u=unit.getText().toString().trim().toLowerCase(Locale.ROOT),e=expiry.getText().toString().trim();double q;try{q=Double.parseDouble(qty.getText().toString());}catch(Exception ex){qty.setError("Enter a valid number");return;}if(n.isEmpty()){name.setError("Name required");return;}if(q<=0||!Double.isFinite(q)){qty.setError("Quantity must be positive");return;}if(!Arrays.asList("g","kg","ml","l","piece","slice").contains(u)){unit.setError("Use g, kg, ml, l, piece or slice");return;}if(!e.isEmpty()&&!e.matches("\\d{4}-\\d{2}-\\d{2}")){expiry.setError("Use YYYY-MM-DD");return;}if(!e.isEmpty())try{java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.ROOT);f.setLenient(false);f.parse(e);}catch(Exception ex){expiry.setError("Invalid calendar date");return;}db.save(id,n,q,u,e);finish();}
}
